import 'package:flutter/material.dart';

import '../../themes/stack_colors.dart';
import '../adaptive_page.dart';
import '../background.dart';

class DesktopScaffold extends StatelessWidget {
  const DesktopScaffold({
    super.key,
    this.background,
    this.appBar,
    this.body,
    this.minBodyHeight = DesktopFit.pageHeight,
    this.bodyGrows = false,
  });

  final Color? background;
  final Widget? appBar;
  final Widget? body;

  /// See [DesktopPageBody.minHeight].
  final double minBodyHeight;

  /// See [DesktopPageBody.growsWithChild].
  final bool bodyGrows;

  @override
  Widget build(BuildContext context) {
    return Material(
      color:
          background ?? Theme.of(context).extension<StackColors>()!.background,
      child: Background(
        child: Column(
          // crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (appBar != null) appBar!,
            if (body != null)
              Expanded(
                child: DesktopPageBody(
                  minHeight: minBodyHeight,
                  growsWithChild: bodyGrows,
                  child: body!,
                ),
              ),
          ],
        ),
      ),
    );
  }
}

class MasterScaffold extends StatelessWidget {
  const MasterScaffold({
    super.key,
    required this.isDesktop,
    required this.appBar,
    required this.body,
    this.background,
    this.maxBodyWidth = ScreenFit.columnWidth,
  });

  final bool isDesktop;
  final Widget appBar;
  final Widget body;
  final Color? background;

  /// On mobile, see [AppScaffold.maxBodyWidth].
  final double maxBodyWidth;

  @override
  Widget build(BuildContext context) {
    if (isDesktop) {
      return DesktopScaffold(
        background: background,
        appBar: appBar,
        body: body,
      );
    } else {
      return Background(
        child: AppScaffold(
          backgroundColor: background ?? Colors.transparent,
          appBar: appBar as PreferredSizeWidget?,
          maxBodyWidth: maxBodyWidth,
          body: SafeArea(child: body),
        ),
      );
    }
  }
}
